  await page.goto(pathToFileURL(path.join(root, 'desktop-start-instructions.html')).href);
  await page.screenshot({ path: out('desktop-start-instructions.png'), fullPage: true });
  await page.close();
}

async function measureCompare(page) {
  const header = page.locator('header');
  const baseline = page.locator('.header-baseline');
  const loadBtn = page.locator('#loadBtn');
  const hb = await header.boundingBox();
  const bb = await baseline.boundingBox();
  const lb = await loadBtn.boundingBox();
  const wrap = await page.evaluate(() => {
    const el = document.querySelector('.header-baseline');
    if (!el) return null;
    const cs = getComputedStyle(el);
    return {
      scrollWidth: document.documentElement.scrollWidth,
      clientWidth: document.documentElement.clientWidth,
      baselineFlexWrap: cs.flexWrap,
      baselineScrollWidth: el.scrollWidth,
      baselineClientWidth: el.clientWidth,
      text: el.innerText.replace(/\s+/g, ' ').trim(),
    };
  });
  const instructions = await page.locator('#dropHint .desktop-instructions').innerText();
  return { headerH: hb?.height, baselineH: bb?.height, loadTop: lb?.y, wrap, instructions };
}

async function shotLive(width, height, name, { compare = false, mobile = false } = {}) {
  const context = await browser.newContext({
    viewport: { width, height },
    deviceScaleFactor: 1,
    hasTouch: mobile,
    isMobile: mobile,
  });
  const page = await context.newPage();
  await page.addInitScript(() => {
    localStorage.setItem('simplify-viewer-tour-v1', '1');
    localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
  });
  await page.goto('http://127.0.0.1:5051/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  if (compare) {
    for (const algo of ['dots', 'dp', 'squish']) {
      await page.locator(`#headerBaselineAlgoRow .baseline-algo-pill[data-algo="${algo}"]`).click();
      await page.waitForTimeout(100);
    }
    // ensure fields visible
    await page.waitForSelector('#headerBaselineLssdField:not([hidden])');
  }
  const metrics = await measureCompare(page);
  await page.screenshot({ path: out(name), fullPage: false });
  await context.close();
  return metrics;
}

